{
  "name": "@stand-e/opencode-slackcode",
  "version": "0.3.45",
  "description": "OpenCode plugin that streams session and agent activity into Slack.",
  "type": "module",
  "main": "dist/index.js",
  "exports": {
    ".": "./dist/index.js"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "slack",
    "agent"
  ],
  "author": "malidong",
  "license": "MIT",
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.json && npx -y esbuild src/plugin-entry.ts --bundle --platform=node --format=esm --outfile=dist/index.js --external:@opencode-ai/plugin && npx -y esbuild src/plugin-entry.ts --bundle --platform=node --format=esm --outfile=dist/slackcode-all.js --external:@opencode-ai/plugin",
    "test": "vitest",
    "prepublishOnly": "npm run build"
  },
  "dependencies": {
    "@slack/web-api": "^7.8.0",
    "js-yaml": "^4.1.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.2.25",
    "@types/js-yaml": "^4.0.9",
    "@types/node": "^22.13.9",
    "typescript": "^5.8.2",
    "vitest": "^3.0.7",
    "esbuild": "^0.25.0"
  }
}
